// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }

    function testFuzz_property(address actor) public {
        // actor is the arbitrary caller whose view of the pause state we check;
        // paused() is callable by anyone and must reflect the internal flag faithfully.
        vm.prank(actor);
        bool p = c.paused();
        // General rule: an undeployed-pause contract reports NOT paused for every caller.
        assertTrue(p == false, "paused() must be false before any pause");
    }
}
